-- DESIGN PROPOSAL ONLY. Not a migration; not applied to any database.
-- Scope: replace creative_run for current brand workflows. Existing pregen
-- builds / audience snapshots can adapt to the shared UI without moving here.
-- IDs are generated by the app. Timestamps are UTC timestamptz.

CREATE TYPE workflow_run_status AS ENUM (
  'queued', 'running', 'succeeded', 'failed', 'cancelled'
);

CREATE TABLE workflow_run (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organization(id) ON DELETE CASCADE,
  brand_id text NOT NULL REFERENCES brand(id) ON DELETE CASCADE,
  workflow_type text NOT NULL,
  workflow_version integer NOT NULL DEFAULT 1 CHECK (workflow_version > 0),

  -- Scope/context, not ownership alternatives. Brand is always required.
  campaign_id text REFERENCES campaign(id) ON DELETE SET NULL,
  document_id text REFERENCES production_packet(id) ON DELETE SET NULL,
  content_post_id text REFERENCES content_post(id) ON DELETE SET NULL,
  thread_id text REFERENCES assistant_thread(id) ON DELETE SET NULL,
  parent_run_id text REFERENCES workflow_run(id) ON DELETE SET NULL,
  retry_of_id text REFERENCES workflow_run(id) ON DELETE SET NULL,

  status workflow_run_status NOT NULL DEFAULT 'queued',
  message text,
  -- Shared schema, e.g. {completed:142,total:164,unit:"cards",failed:2,
  -- remaining:20,steps:[{key:"catalog",label:"Prepare catalog",status:"running"}]}.
  -- completed counts successful output units, never failed or skipped units.
  -- Counters are optional. Steps are not assumed to have equal duration.
  progress jsonb NOT NULL DEFAULT '{}'::jsonb,
  input jsonb NOT NULL,
  checkpoint jsonb NOT NULL DEFAULT '{}'::jsonb,
  result jsonb,
  error jsonb, -- {code,message}; detailed provider diagnostics stay server-side.

  -- Request replay vs resource concurrency are separate concerns.
  -- Retry gets a new idempotency key. Handler output keys remain stable where
  -- continuing existing work, so retries cannot silently duplicate artifacts.
  idempotency_key text NOT NULL,
  lock_key text NOT NULL, -- e.g. document:<id>, catalog:<brand>, ads-batch:<id>
  claim_token uuid,
  lease_expires_at timestamptz,

  -- Used only by a workflow backed by one external asynchronous request.
  -- Multi-provider work keeps per-step details in its typed checkpoint.
  provider text,
  provider_request_id text,
  webhook_token_hash text,

  created_by text REFERENCES "user"(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  started_at timestamptz,
  updated_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,

  CHECK (parent_run_id IS DISTINCT FROM id),
  CHECK (retry_of_id IS DISTINCT FROM id),
  CHECK (jsonb_typeof(progress) = 'object'),
  CHECK (jsonb_typeof(input) = 'object'),
  CHECK (jsonb_typeof(checkpoint) = 'object'),
  CHECK (provider_request_id IS NULL OR provider IS NOT NULL),
  CHECK ((status IN ('succeeded','failed','cancelled')) = (finished_at IS NOT NULL)),
  CHECK (status <> 'running' OR (claim_token IS NOT NULL AND lease_expires_at IS NOT NULL AND started_at IS NOT NULL))
);

CREATE UNIQUE INDEX workflow_run_request ON workflow_run
  (organization_id, workflow_type, idempotency_key);
-- Multiple jobs may queue for a resource; only one may execute at a time.
CREATE UNIQUE INDEX workflow_run_resource_claim ON workflow_run
  (organization_id, lock_key) WHERE status = 'running';
CREATE UNIQUE INDEX workflow_run_provider_request ON workflow_run
  (provider, provider_request_id) WHERE provider_request_id IS NOT NULL;
CREATE INDEX workflow_run_brand_activity ON workflow_run
  (organization_id, brand_id, created_at DESC);
CREATE INDEX workflow_run_active_lease ON workflow_run
  (lease_expires_at) WHERE status = 'running';
CREATE INDEX workflow_run_queue ON workflow_run
  (created_at) WHERE status = 'queued';
CREATE INDEX workflow_run_document ON workflow_run (document_id, created_at DESC);
CREATE INDEX workflow_run_parent ON workflow_run (parent_run_id);

-- A frozen export is a permanent output, not run progress. Create it only once
-- ready; unfinished render assets/checkpoints belong to the running workflow.
CREATE TABLE catalog_export (
  id text PRIMARY KEY,
  organization_id text NOT NULL REFERENCES organization(id) ON DELETE CASCADE,
  brand_id text NOT NULL REFERENCES brand(id) ON DELETE CASCADE,
  source_run_id text UNIQUE REFERENCES workflow_run(id) ON DELETE SET NULL,
  label text NOT NULL,
  input_snapshot jsonb NOT NULL, -- exact cards, homes, formats and rendering config
  feed_rows jsonb NOT NULL,
  assets jsonb NOT NULL, -- validated {homeId,assetId,url,format,renderKey,reused}[]
  folder_id text, -- convenience grouping; assets retain their own library records
  primary_format text NOT NULL,
  created_by text REFERENCES "user"(id) ON DELETE SET NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (jsonb_typeof(input_snapshot) = 'object'),
  CHECK (jsonb_typeof(feed_rows) = 'array'),
  CHECK (jsonb_typeof(assets) = 'array')
);
CREATE INDEX catalog_export_brand ON catalog_export (organization_id, brand_id, created_at DESC);

-- REQUIRED SERVICE CONTRACT (the DDL alone is not the execution system):
-- 1. authorizeAndStart validates workspace membership and same-brand ownership
--    of ALL scope IDs, parent/retry IDs and input references. FKs only check
--    existence. Parent relations are immutable and cannot form cycles.
-- 2. A registry keyed by workflow_type + workflow_version validates input,
--    checkpoint, result, progress, and error. It derives display labels,
--    authorized destinations and supported actions; do not store UI URLs here.
-- 3. claim atomically transitions queued -> running with a fresh claim token,
--    lease and resource lock. Every heartbeat/progress/completion write is
--    conditional on that token AND running status. Affected row count matters.
-- 4. Completion commits local output records and final run state together where
--    possible. Provider callbacks are authenticated and reconciled idempotently.
--    This is not an exactly-once guarantee for external effects.
-- 5. Expired leases need a sweeper/reconciler and reliable dispatch. Do not just
--    replace a stale running worker and repeat external requests blindly.
--    Document editing is locked while queued/running; provider results retain
--    the input revision so late output cannot overwrite newer human edits.
-- 6. A failed retry is a new row linked via retry_of_id. Handler decides
--    whether to resume a checkpoint or restart. UI never assumes retry is safe.
-- 7. Root runs display once in the client jobs area; child progress belongs under
--    the parent. Parent status aggregates child failures. A failed attempt with
--    a newer retry is in history, not a second banner. Success goes to history.
-- 8. Input/model prompts, callback secrets and provider payloads are excluded
--    from the public status DTO. It exposes only authorized summary fields.
-- 9. Successful generation is separate from creative approval, acceptance and
--    delivery. production_packet, ad, media_asset and message_send retain those
--    business states. Result JSON may stage provider candidates until acceptance;
--    accepted media and frozen exports must survive workflow history deletion.

-- 10. No partial lifecycle state. Incomplete REQUIRED work is failed, even when
--     useful outputs were saved. Counts/checkpoints preserve that progress.
--     Non-blocking warnings may accompany succeeded; each handler defines its
--     required outputs. Cancellation is distinct from execution failure.
-- 11. The UI invalidates affected queries / refreshes server content as outputs
--     land. An observed active -> succeeded transition emits one completion
--     toast per run; initial history loads and repeated polls do not replay it.
--     Keep result previews in their destination UI, not in the job banner.
